137	// A derived dataset already has its own downstream; a request mixing an
138	// independent, non-cyclic source with that downstream must be refused as a
139	// whole, naming the downstream that closes the multi-level loop. Shared
140	// ancestry between candidate upstreams must neither hide that loop nor turn a
141	// benign merge into one.
142	func TestRegisterIndependentSourceMixedWithOwnDownstreamRejected(t *testing.T) {
143		graph := map[string]*Lineage{}
144		mustRegister(t, graph, "src")
145		mustRegister(t, graph, "extra")
146		mustRegister(t, graph, "mid", "src")
147		mustRegister(t, graph, "leaf", "mid")
148		before := snapshot(graph)
149	
150		// Independent source first, cyclic own-downstream second.
151		err := Register(graph, Dataset{Name: "mid"}, []string{"extra", "leaf"})
152		if err == nil || !strings.Contains(err.Error(), "cycle") || !strings.Contains(err.Error(), "leaf") {
153			t.Fatalf("want cycle error naming leaf, got %v", err)
154		}
155		if !reflect.DeepEqual(snapshot(graph), before) {
156			t.Fatalf("rejected registration changed graph: before=%v after=%v", before, snapshot(graph))
157		}
158		assertEntry(t, graph, "mid", []string{"src"}, []string{"leaf"})
159		assertEntry(t, graph, "extra", nil, nil)
160		assertConsistent(t, graph)
161	
162		// The same offending downstream listed first reports the same named error;
163		// input order must not swap it for any other complaint.
164		err = Register(graph, Dataset{Name: "mid"}, []string{"leaf", "extra"})
165		if err == nil || !strings.Contains(err.Error(), "cycle") || !strings.Contains(err.Error(), "leaf") {
166			t.Fatalf("want cycle error naming leaf, got %v", err)
167		}
168		if !reflect.DeepEqual(snapshot(graph), before) {
169			t.Fatalf("rejected registration changed graph: before=%v after=%v", before, snapshot(graph))
170		}
171	
172		// Without the cyclic upstream the replacement succeeds, keeping mid's own
173		// downstream leaf and gaining no new child for the refused attempts.
174		mustRegister(t, graph, "mid", "extra")
175		assertEntry(t, graph, "mid", []string{"extra"}, []string{"leaf"})
176		assertEntry(t, graph, "extra", nil, []string{"mid"})
177		assertEntry(t, graph, "src", nil, nil)
178		assertConsistent(t, graph)
179	
180		// Later registrations judge cycles against the current edges, not any
181		// conclusion cached before mid moved: extra -> mid now closes a loop.
182		if err := Register(graph, Dataset{Name: "extra"}, []string{"mid"}); err == nil ||
183			!strings.Contains(err.Error(), "cycle") || !strings.Contains(err.Error(), "mid") {
184			t.Fatalf("want cycle error naming mid under the new edges, got %v", err)
185		}
186	}
