		fmt.Printf("CommonUpstreams(%q, %q) error: %v\n", "", "right", err)
	}
	if _, err := chainledger.CommonUpstreams(graph, "left", "ghost"); err != nil {
		fmt.Printf("CommonUpstreams(%q, %q) error: %v\n", "left", "ghost", err)
	}
}

